    private Document.OutputSettings out;

    @Test
    public void nodeName() {
        Comment comment = new Comment("data");
        assertThat(comment.nodeName(), is("#comment"));
    }

    @Test
    public void getData() {
        Comment comment = new Comment("data");
        assertEquals("data", comment.getData());
    }

    @Test
    public void setData() {
        String data = "newData";
        Comment comment = new Comment("oldData");
        when(comment.coreValue(data)).thenReturn(comment);
        Comment expectedComment = new Comment(data);
        assertThat(expectedComment, is(comment));
        assertEquals(data, expectedComment.getData());
    }

    @Test
    public void outerHtmlHead() {
        Comment comment = new Comment("data");
        when(out.prettyPrint()).thenReturn(true);
        when(accum.append(anyString())).thenReturn(accum);
        when(accum.length()).thenReturn(0);

        Comment expectedComment = new Comment("data");
        when(comment.coreValue()).thenReturn(data -> data);
        expectedComment.outerHtmlHead(accum, 1, out);
    }

    @Test
