        when(out.outline()).thenReturn(true);
        when(accum.append(anyString())).thenReturn(accum);

        Comment expectedComment = new Comment("data");
        expectedComment.outerHtmlTail(accum, 1, out);
    }

    @Test
    public void outerHtml() {
